import json,numpy as np
from PIL import Image,ImageDraw
m=json.load(open('/app/output/bedscan2/meta.json'));c=m['cameras']['robot_r1:zed_link:Camera:0'];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:3,:3];t=E[:3,3];d=np.load('/app/output/bedscan2/last_depth_robot_r1:zed_link:Camera:0.npy');v,u=np.mgrid[:224,:224];z=d;pc=np.stack(((u-K[0,2])/K[0,0]*z,(v-K[1,2])/K[1,1]*z,z),axis=-1).reshape(-1,3);pw=(pc-t)@R
W,H=1000,850;xmin,xmax=-2.5,1.0;ymin,ymax=-2.2,1.4
im=Image.new('RGB',(W,H),'white');dr=ImageDraw.Draw(im)
def cv(x,y):return int((xmax-x)/(xmax-xmin)*(W-1)),int((ymax-y)/(ymax-ymin)*(H-1))
for xx in np.arange(-2.5,1.1,.2):dr.line((cv(xx,ymin),cv(xx,ymax)),fill=(225,225,225))
for yy in np.arange(-2.2,1.5,.2):dr.line((cv(xmin,yy),cv(xmax,yy)),fill=(225,225,225))
for x,y,h in pw:
 if x<xmin or x>xmax or y<ymin or y>ymax or h<.08 or h>1.2:continue
 px,py=cv(x,y);c=(int(255*min(1,h/.8)),20,int(255*(1-min(1,h/.8))));dr.point((px,py),fill=c)
for x,y,label,col in [(.707,-.009,'robot','red'),(-1.775,.426,'red can','green'),(-.422,.385,'orange picked','orange')]:
 px,py=cv(x,y);dr.ellipse((px-7,py-7,px+7,py+7),outline=col,width=3);dr.text((px+10,py-10),label,fill='black')
im.save('/app/output/bedscan2/topdown.png')
PY

